entries.syntax_block:
// модуль ролі
Procedure OnAccessRead(Source, Operation, Allowed)
{
    Source = Source.Where(Function(x) { Return x.Code = "13"; });
    Allowed = True;
}

entries.syntax_block_ves:
// модуль ролі
Procedure OnAccessRead(Source, Operation, Allowed)
    Source = Source.Where(Function(x) Return x.Code = "13"; EndFunction);
    Allowed = True;
EndProcedure

entries.example:
// відбір за поточним користувачем через регістр доступу
Procedure OnAccessRead(Source, Operation, Allowed)
{
    if (Source = "Catalog.Товари") {
        Source = restrict s in Source
                     join a in Data.Registers.ДоступДоСкладів.Where(Function(a) { Return a.Користувач = CurrentUser(); })
                         on s.Склад = a.Склад;
    }
    Allowed = True;
}

