// розіменування через крапку працює: платформа сама побудує з'єднання
Procedure OnAccessRead(Source, Operation, Allowed)
{
    if (Source = "Document.Видаткова") {
        Source = Source.Where(Function(x) { Return x.Договір.Організація = ПоточнаОрганізація(); });
    }
    Allowed = True;
}

entries.syntax_block:
Procedure OnAccessWrite(Source, Operation, Allowed)
{
    if (Source = "Catalog.Товари") {
        if (Operation = "Delete") {
            Allowed = False;
            Return;
        }
        Source = Source.Where(Function(x) { Return x.Склад = ПоточнийСклад(); });
    }
    Allowed = True;
}

